import { Err } from "../utils/err.ts";
import type { Result } from "../types/result.ts";
import { BaseSegment } from "../types/segment.ts";
import type { EncodingCharacters } from "../types/encoding.ts";
import { ParserUtils } from "../types/parser.ts";


/**
 * RDT - Table Row Data (HL7 v2.7)
 */
export class RDT extends BaseSegment {
  /** The HL7 segment identifier. */
  name = "RDT";

  constructor() {
    super();
    this.fields = [];
  }

  /** RDT-1 Column Value (varies, max 0, required) (chainable). */
  columnValue(value: string): this {
    this.fields[0] = this.createField(value);
    return this;
  }

  /** Parses the input string into a structured instance. */
  static parse(
    segmentString: string,
    encoding: EncodingCharacters,
  ): Result<RDT> {
    const parts = segmentString.split(encoding.fieldSeparator);
    if (parts[0] !== "RDT") {
      return { ok: false, err: new Err(`Expected RDT segment, got ${parts[0]}`) };
    }
    const seg = new RDT();
    for (let i = 1; i < parts.length; i++) {
      seg.fields[i - 1] = ParserUtils.parseField(parts[i], encoding);
    }
    return { ok: true, val: seg };
  }
}
